set -euo pipefail
upload_dir=$(getent passwd "$SUDO_USER" | cut -d: -f6)
cd /opt/news-flow/current
runuser -u news-flow -- /opt/news-flow/node/bin/node --input-type=module - <<'NODE'
import fs from 'node:fs';import {gzipSync} from 'node:zlib';import {createHash} from 'node:crypto';import {loadNewsRegistry} from './src/newsFlow/registry.mjs';import {NewsHttpDriver,NewsProxyPool} from './src/newsFlow/transport.mjs';import {NewsNetworkPool} from './src/newsFlow/networkPool.mjs';import {parsePublicPublicationFeed} from './src/web/newsDateContext.mjs';const root='/var/lib/news-flow/qc-public24-20261123',registry=await loadNewsRegistry(),pool=await NewsProxyPool.load('/etc/news-flow/proxies.json',{rotation:'request'}),network=new NewsNetworkPool({workers:2}),driver=new NewsHttpDriver({state:{cacheResponses:false,failedUrl:()=>false,request:()=>null,reserve:()=>true,cache:()=>null,completeHttpResponse:()=>{}},network,pool,allowedDomains:registry.allowedDomains,siteCooldown:false,maxWireRequests:18}),r={at:new Date().toISOString(),checks:[]};
async function check(site,url,kind,headers={}){const p=await driver.get('qc24-last-'+r.checks.length,url,registry.sources.get(site).config,[],{reviewFailed:true,taskRole:'publisher_dependency',headers}),o={site,url,kind,error:p.error,statusCode:p.statusCode,finalUrl:p.finalUrl};if(p.html){o.file=root+'/evidence/'+createHash('sha256').update(p.html).digest('hex')+'.gz';fs.writeFileSync(o.file,gzipSync(p.html));if(!p.error){try{const d=JSON.parse(p.html);o.jsonKeys=Object.keys(d).slice(0,15);o.nativePublicationFields=[...new Set(p.html.match(/\b(?:datePublished|date_gmt|publish_date|first_publish_date|display_date|created_at|published_at)\b/g)||[])];}catch{}}}r.checks.push(o);console.log(JSON.stringify(o));return p;}
try{const feedUrl='https://www.coindesk.com/arc/outboundfeeds/rss/?outputType=xml',p=await check('coindesk.com',feedUrl,'fresh_official_rss'),f=!p.error?parsePublicPublicationFeed(p.html,p.finalUrl||feedUrl):null;r.coinDeskItems=f?.items.length||0;const item=f?.items.find(i=>/\/20\d\d\/\d\d\/\d\d\//.test(new URL(i.url).pathname));if(item){const path=new URL(item.url).pathname;r.latestCoinDeskUrl=item.url;r.latestCoinDeskPublication=item.iso;for(const [name,query] of [['article-by-url-v1',{website_url:path}],['content-search',{website_url:path,from:0,size:1}]])await check('coindesk.com','https://www.coindesk.com/pf/api/v3/content/fetch/'+name+'?query='+encodeURIComponent(JSON.stringify(query))+'&_website=coindesk','legacy_publisher_content_api',{Accept:'application/json'});}
for(const site of ['tieudungso.vn','gialaitv.vn']){const cfg=registry.sources.get(site).config;for(const url of (cfg.discovery?.categories||[]).filter(u=>typeof u==='string'&&!u.includes('/feed/')).slice(0,4))await check(site,url,'configured_category_control');}
r.finishedAt=new Date().toISOString();fs.writeFileSync(root+'/last-routes.json',JSON.stringify(r,null,2));}finally{await network.close();}
NODE
install -o "$SUDO_USER" -m 0600 /var/lib/news-flow/qc-public24-20261123/last-routes.json "$upload_dir/.qc-public24-last-routes.json"
